<?php
namespace App\Console\Commands;
use App\Enums\AppointmentStatus; use App\Enums\PaymentStatus; use App\Models\Appointment; use App\Services\SlotCacheService; use Illuminate\Console\Command; use Illuminate\Support\Facades\DB;
class ExpireAppointmentHolds extends Command { protected $signature='appointments:expire-holds'; protected $description='Expire unpaid appointment holds that passed their deadline.'; public function handle(SlotCacheService $cache): int { $count=0; Appointment::where('status',AppointmentStatus::Pending->value)->where('hold_expires_at','<=',now())->chunkById(100,function($rows) use(&$count,$cache){foreach($rows as $a){DB::transaction(function() use($a,$cache,&$count){$locked=Appointment::whereKey($a->id)->lockForUpdate()->first();if(!$locked||$locked->status!==AppointmentStatus::Pending||$locked->hold_expires_at?->isFuture()){return;}$locked->update(['status'=>AppointmentStatus::Expired]);$locked->payment()->where('status',PaymentStatus::Pending->value)->update(['status'=>PaymentStatus::Failed->value]);$cache->invalidate($locked->provider_id);$count++;});}});$this->info("Expired {$count} holds.");return self::SUCCESS;} }
